---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Profile menu: The account menu behind an avatar: switch workspace, theme, shortcuts and sign out.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change profile-menu.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './profile-menu.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" or "clean" draws it in that style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft" or "clean") */
  'data-style'?: 'soft' | 'clean';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', className]} data-c="profile-menu" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="pfm">
  <div class="pfm-bar panel">
    <span class="pfm-lg pfm-cur"></span><span class="pfm-ws"><b class="pfm-wn"></b><span class="muted">Pricing refresh</span></span>
    <button class="pfm-tr" aria-haspopup="menu" aria-expanded="false" aria-label="Account menu, Maya Kim" data-pop-align="end" data-pop-pos="down"><span class="av">MK</span><svg class="i xs"><use href="#i-chev-d"/></svg></button>
    <button class="pill line sm pfm-in" hidden>Sign in</button>
  </div>
  <div class="pop pfm-pop" role="menu">
    <div class="pfm-me" role="none"><span class="av">MK</span><span class="t"><b class="pfm-nm">Maya Kim</b><span class="muted pfm-em">maya@northwind.studio</span></span></div>
    <div class="sep" role="separator"></div>
    <div class="pfm-grp" role="group"><div class="ph pfm-gl" role="none">Workspaces</div><div class="pfm-wsl"></div></div>
    <div class="sep" role="separator"></div>
    <button class="mi pfm-th" role="menuitemcheckbox" aria-checked="false" tabindex="-1"><svg class="i s"><use href="#i-moon"/></svg><span>Dark theme</span><span class="toggle" aria-hidden="true"></span></button>
    <button class="mi pfm-ky" role="menuitem" tabindex="-1"><svg class="i s"><use href="#i-keyboard"/></svg><span>Keyboard shortcuts</span><span class="kbd" aria-hidden="true">?</span></button>
    <div class="sep" role="separator"></div>
    <button class="mi pfm-out" role="menuitem" tabindex="-1"><svg class="i s"><use href="#i-logout"/></svg><span>Sign out</span></button>
  </div>
  <div class="fold shut pfm-kf"><div><div class="pfm-keys panel" role="region" aria-label="Keyboard shortcuts">
    <div class="pfm-kh"><b>Keyboard shortcuts</b><button class="ib pfm-kx" aria-label="Close shortcuts" data-tip="Close"><svg class="i xs"><use href="#i-x"/></svg></button></div>
    <dl class="pfm-kl"><div><dt><span class="kbd">↑</span><span class="kbd">↓</span></dt><dd>Move through the menu</dd></div><div><dt><span class="kbd">Home</span><span class="kbd">End</span></dt><dd>First or last item</dd></div><div><dt><span class="kbd">Esc</span></dt><dd>Close the menu</dd></div><div><dt><span class="kbd">?</span></dt><dd>Show these shortcuts</dd></div></dl>
  </div></div></div>
  <p class="pfm-note" aria-live="polite"></p>
</div>
  </Fragment></div>
</div>
<script>
  import './profile-menu.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Profile menu ---------- */
/* an app's top bar with the account behind the avatar. The menu opens under it, lined up with its right edge, over the room
   the component keeps for it under the bar, so the bar never moves as the menu opens and shuts (owner, 20 Nov: menus open over
   the component from their trigger and never move it) and the menu is never cut off. The bar's content sits 16px in all round
   in every style: the workspace's tile on the left, the avatar's chevron on the right, its hover box reaching out round it */
.pfm{position:relative;width:100%;max-width:400px;margin:0 auto;display:flex;flex-direction:column;gap:12px}
.pfm-bar{display:flex;align-items:center;gap:12px;min-height:64px;padding:12px;padding-left:16px;border-radius:var(--dm-r-card)}
/* a workspace's tile is its identity mark: in Soft and Blueprint a vivid fill with its own ink, the avatars' colours (white on
   blue, violet, red and pink; 4.5:1 and APCA Lc 60); Clean keeps its marks monochrome */
.pfm-lg{--dm-tb:var(--dm-chip);--dm-tc:var(--dm-fg2);width:28px;height:28px;border-radius:var(--dm-r-sm);display:grid;place-items:center;flex:none;font-size:12px;font-weight:500;background:var(--dm-tb);color:var(--dm-tc);transition:background var(--dm-t) var(--dm-ease),color var(--dm-t) var(--dm-ease)}
.pfm-lg[data-t="pb"]{--dm-tb:var(--dm-av-b);--dm-tc:var(--dm-av-b-ink)}.pfm-lg[data-t="pl"]{--dm-tb:var(--dm-av-l);--dm-tc:var(--dm-av-l-ink)}.pfm-lg[data-t="pr"]{--dm-tb:var(--dm-av-r);--dm-tc:var(--dm-av-r-ink)}.pfm-lg[data-t="pk"]{--dm-tb:var(--dm-av-k);--dm-tc:var(--dm-av-k-ink)}
.pfm-lg[data-t="pm"]{--dm-tb:var(--dm-av-m);--dm-tc:var(--dm-av-m-ink)}.pfm-lg[data-t="pt"]{--dm-tb:var(--dm-av-t);--dm-tc:var(--dm-av-t-ink)}.pfm-lg[data-t="py"]{--dm-tb:var(--dm-av-y);--dm-tc:var(--dm-av-y-ink)}.pfm-lg[data-t="pp"]{--dm-tb:var(--dm-av-p);--dm-tc:var(--dm-av-p-ink)}
.pfm-ws{flex:1;min-width:0;display:flex;flex-direction:column}
.pfm-wn{font-size:13.5px;line-height:18px;font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%}
.pfm-ws .muted{font-size:12px;line-height:16px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.pfm-tr{display:flex;align-items:center;gap:6px;height:40px;padding:0 4px 0 6px;border-radius:var(--dm-r-pill);color:var(--dm-muted);flex:none;transition:background-color var(--dm-t-fast) var(--dm-ease)}
.pfm-tr[aria-expanded="true"]{background:color-mix(in srgb,var(--dm-fg) 5%,transparent)}
@media (hover:hover) and (pointer:fine){.pfm-tr:hover{background:color-mix(in srgb,var(--dm-fg) 5%,transparent)}}
.pfm-tr .av,.pfm-me .av{background:var(--dm-av-l);color:var(--dm-av-l-ink)}
.pfm-tr .av{width:28px;height:28px;font-size:11px}
.pfm-tr>.i{transition:transform var(--dm-t) var(--dm-ease)}
.pfm-tr[aria-expanded="true"]>.i{transform:rotate(180deg)}
.pfm-in{flex:none;margin-right:4px}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov); Clean's ink primary alone presses. The same goes for the
   other menus of this group (Context switcher, Filter menu, Context menu) and Ticket list */
.pfm :is(.pill,.ib):active,:root[data-style="clean"] :is(.pfm,.csw,.flm,.cxm,.tkx) .ib:active,:root [data-style="clean"] :is(.pfm,.csw,.flm,.cxm,.tkx) .ib:active,:root [data-style="clean"]:is(.pfm,.csw,.flm,.cxm,.tkx) .ib:active{transform:none}
/* the rows of these menus hover, and show the item picked, with a quiet fill that shows in light mode too (the owner's batch 2
   notes: a hover fill shows on whatever it sits on; --dm-row barely shows on a white menu) */
@media (hover:hover) and (pointer:fine){:is(.pfm-pop,.flm-pop,.cxm-pop,.cxm-pop2) .mi:is(:hover,.hl,[role="menuitemradio"][aria-checked="true"]){background:color-mix(in srgb,var(--dm-fg) 5%,transparent)}}
.pfm-pop{width:256px}
.pfm-me{display:flex;align-items:center;gap:10px;padding:var(--dm-s-2) var(--dm-s-2) 6px}
.pfm-me .av{width:32px;height:32px;font-size:12px}
.pfm-me .t{min-width:0;display:flex;flex-direction:column;line-height:1.35}
.pfm-me b{font-size:13.5px;font-weight:500}
.pfm-me .muted{font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.pfm-pop .mi .pfm-lg{width:24px;height:24px;font-size:11px;border-radius:calc(7px * var(--dm-rk-m,var(--dm-rk)))}
.pfm-pop .mi .d{white-space:nowrap}
/* the theme row is a switch: on, it shows the switch on rather than a selected row */
.pfm-th[aria-checked="true"]{background:none;font-weight:400}
.pfm-th.hl{background:color-mix(in srgb,var(--dm-fg) 5%,transparent)}
@media (hover:hover) and (pointer:fine){.pfm-th[aria-checked="true"]:hover{background:color-mix(in srgb,var(--dm-fg) 5%,transparent)}}
.pfm-th .toggle{margin-left:auto}
.pfm-th[aria-checked="true"] .toggle{background:var(--dm-accent);box-shadow:inset 0 0 0 1px var(--dm-accent-mark,var(--dm-accent))}
.pfm-th[aria-checked="true"] .toggle::after{transform:translateX(12px);background:var(--dm-on-accent)}
.pfm-ky .kbd{margin-left:auto}
/* the shortcuts: a plain list of keys and what they do, 16px in from every edge; Close sits on the title's line with its glyph
   16px in */
.pfm-keys{padding:var(--dm-s-4);border-radius:var(--dm-r-card)}
.pfm-kh{display:flex;align-items:center;justify-content:space-between;gap:var(--dm-s-2);height:20px;margin-bottom:var(--dm-s-3);font-size:13.5px}
.pfm-kh b{font-weight:500}
.pfm-kh .ib{width:26px;height:26px;margin:-3px -7px -3px 0}
.pfm-kl{margin:0;display:flex;flex-direction:column;gap:var(--dm-s-2)}
.pfm-kl>div{display:flex;align-items:center;gap:var(--dm-s-3);font-size:12.5px}
.pfm-kl dt{display:flex;gap:var(--dm-s-1);width:88px;flex:none}
.pfm-kl dd{margin:0;color:var(--dm-fg2);min-width:0}
/* what changed (a switch, the theme, signing out) is said to screen readers only: the bar and the menu already show it, so no
   line of text repeats it under the bar (owner, 18 Nov) */
.pfm-note{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
/* Clean: the bar is a card with 22px corners; the tiles are monochrome; the menu takes the card's corners with its rows
   concentric inside them; the theme switch is ink when on; the shortcuts card has an off-white head strip with Close a 28px
   circle 16px from its top and right edges (owner, 23 Nov) */
:root[data-style="clean"] .pfm-lg[data-t],:root [data-style="clean"] .pfm-lg[data-t],:root [data-style="clean"].pfm-lg[data-t]{background:var(--dm-chip);color:var(--dm-fg2);box-shadow:inset 0 0 0 1px var(--dm-hair)}
:root[data-style="clean"] .pfm-pop,:root [data-style="clean"] .pfm-pop,:root [data-style="clean"].pfm-pop{padding:6px;border-radius:var(--dm-r-card)}
:root[data-style="clean"] .pfm-pop .mi,:root [data-style="clean"] .pfm-pop .mi,:root [data-style="clean"].pfm-pop .mi{border-radius:calc(var(--dm-r-card) - 6px)}
:root[data-style="clean"] .pfm-th[aria-checked="true"] .toggle,:root [data-style="clean"] .pfm-th[aria-checked="true"] .toggle,:root [data-style="clean"].pfm-th[aria-checked="true"] .toggle{background:var(--dm-btn-2);box-shadow:inset 0 0 0 1px var(--dm-btn-2),inset 0 2px 4px -1px rgba(0,0,0,.3)}
:root[data-style="clean"] .pfm-th[aria-checked="true"] .toggle::after,:root [data-style="clean"] .pfm-th[aria-checked="true"] .toggle::after,:root [data-style="clean"].pfm-th[aria-checked="true"] .toggle::after{background:var(--dm-on-btn)}
:root[data-style="clean"] .pfm-keys,:root [data-style="clean"] .pfm-keys,:root [data-style="clean"].pfm-keys{padding:0 16px 16px}
:root[data-style="clean"] .pfm-kh,:root [data-style="clean"] .pfm-kh,:root [data-style="clean"].pfm-kh{height:auto;margin:0 -16px 16px;padding:var(--dm-strip-y) 16px;background:var(--dm-strip);border-bottom:1px solid var(--dm-line);border-radius:var(--dm-r-card) var(--dm-r-card) 0 0;line-height:28px}
:root[data-style="clean"] .pfm-kh .ib,:root [data-style="clean"] .pfm-kh .ib,:root [data-style="clean"].pfm-kh .ib{width:28px;height:28px;margin:0}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, I, REDUCE, hideTip, placePop } from '../core/core.js';
DM.def('profile-menu', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{chev}', I('chev-d','xs')).replace('{moon}', I('moon')).replace('{keyboard}', I('keyboard')).replace('{logout}', I('logout')).replace('{x}', I('x','xs'));
  // the workspaces this account belongs to: initial, name, plan and the tint of its tile
  const WS = [['N', 'Northwind', 'Pro, 12 members', 'pb'], ['A', 'Acme Labs', 'Free, 3 members', 'pk'], ['P', 'Personal', 'Just you', 'pl']];
  const uid = Math.random().toString(36).slice(2, 7);
  const tr = $('.pfm-tr', r), pop = $('.pfm-pop', r), wsl = $('.pfm-wsl', r), th = $('.pfm-th', r), note = $('.pfm-note', r), kf = $('.pfm-kf', r), sin = $('.pfm-in', r), cur = $('.pfm-cur', r), wn = $('.pfm-wn', r);
  // the menu is named by the account it belongs to, and the workspaces by their heading
  $('.pfm-nm', r).id = 'pfm-nm-' + uid; $('.pfm-em', r).id = 'pfm-em-' + uid; $('.pfm-gl', r).id = 'pfm-gl-' + uid;
  pop.setAttribute('aria-labelledby', `pfm-nm-${uid} pfm-em-${uid}`); $('.pfm-grp', r).setAttribute('aria-labelledby', 'pfm-gl-' + uid);
  wsl.innerHTML = WS.map((w, i) => `<button class="mi" role="menuitemradio" aria-checked="${!i}" tabindex="-1" data-i="${i}"><span class="pfm-lg" data-t="${w[3]}">${w[0]}</span><span>${w[1]}<span class="d">${w[2]}</span></span><span class="ck">${I('check','xs')}</span></button>`).join('');
  const rows = $$('.mi', wsl), items = () => $$('.mi', pop);
  // the theme switch starts from the page's own theme
  const root = document.documentElement;
  let ws = 0, dark = root.dataset.theme ? root.dataset.theme === 'dark' : matchMedia('(prefers-color-scheme: dark)').matches;
  // what changed is said to screen readers; the bar and the menu show it, so it has no line of its own under the bar
  const say = t => { note.textContent = t || ''; };
  function paint(){
    const w = WS[ws]; cur.textContent = w[0]; cur.dataset.t = w[3];
    rows.forEach((m, i) => m.setAttribute('aria-checked', i === ws)); th.setAttribute('aria-checked', dark);
  }
  // the workspace name in the bar crossfades to the new one. Each switch replaces the one before it, so switching again
  // before the fade has finished (or straight back) still ends on the workspace you picked, never on an empty line
  let named = WS[0][1], nameT = 0;
  const setName = t => {
    clearTimeout(nameT); wn.classList.add('sw');
    if (t === named){ wn.textContent = t; wn.classList.remove('out'); return; }
    wn.classList.add('out');
    nameT = setTimeout(() => { named = t; wn.textContent = t; wn.classList.remove('out'); }, REDUCE ? 0 : 170);
  };
  c.offs.push(() => clearTimeout(nameT));
  wn.textContent = named; paint();
  // the menu opens and closes on its own rather than through the page's shared popover, so a story playing in the card
  // beside it can't close it. Closing it while the focus is inside gives the focus back to the avatar
  const isOpen = () => pop.classList.contains('open');
  // the focus is the one highlight: a row the demo's pointer left lit goes dark
  const focusItem = m => { if (!m) return; items().forEach(x => { x.tabIndex = x === m ? 0 : -1; x.classList.remove('hl'); }); m.focus({ preventScroll:true }); };
  function show(on, focus){
    if (on && !isOpen()){ hideTip(); placePop(tr, pop); }
    pop.classList.toggle('open', on); pop.inert = !on; tr.setAttribute('aria-expanded', on);
    if (on && focus){ const all = items(); focusItem(focus === 'last' ? all[all.length - 1] : all[0]); }
    if (!on){ items().forEach(x => x.classList.remove('hl')); if (pop.contains(document.activeElement)) tr.focus({ preventScroll:true }); }
  }
  show(false);
  // the menu opens over whatever sits under the bar, so the component keeps room for it below the bar: centred in a
  // stage, the open menu still ends inside it
  const room = () => { const el = $('.pfm', r); el.style.minHeight = Math.ceil($('.pfm-bar', r).offsetHeight + 6 + pop.offsetHeight) + 'px'; };
  room(); if (document.fonts) document.fonts.ready.then(() => { if (!c.dead) room(); });
  c.on(window, 'resize', room);
  // the avatar opens it with a click, Enter, Space or the down arrow, and the focus goes to the first item; the up arrow
  // opens it on the last. A story's tap opens it without moving the focus
  c.on(tr, 'click', e => show(!isOpen(), e.isTrusted && 'first'));
  c.on(tr, 'keydown', e => { if (e.key === 'ArrowDown' || e.key === 'ArrowUp'){ e.preventDefault(); show(true, e.key === 'ArrowUp' ? 'last' : 'first'); } });
  c.on(document, 'pointerdown', e => { if (isOpen() && !pop.contains(e.target) && !tr.contains(e.target)) show(false); });
  c.on(window, 'resize', e => { if (e.isTrusted) show(false); });
  // inside the menu: the arrow keys move and wrap, Home and End jump to the ends, Escape closes it, Tab leaves it
  c.on(pop, 'keydown', e => {
    const all = items(), i = all.indexOf(document.activeElement);
    const go = { ArrowDown:all[(i + 1) % all.length], ArrowUp:all[(i - 1 + all.length) % all.length], Home:all[0], End:all[all.length - 1] }[e.key];
    if (go){ e.preventDefault(); focusItem(go); }
    else if (e.key === 'Escape'){ e.preventDefault(); e.stopPropagation(); show(false); }
    else if (e.key === 'Tab') setTimeout(() => show(false));
  });
  rows.forEach((m, i) => m.addEventListener('click', () => {
    show(false); if (i === ws) return;
    ws = i; paint(); setName(WS[ws][1]); say(`Switched to ${WS[ws][1]}`);
  }));
  // the theme is a switch: the menu stays open so the change shows where it was made
  // a real click switches the page too, through its own theme button where there is one; the preview's story only flips the
  // switch, so the page doesn't flash between themes while the demo loops
  const pageDark = () => root.dataset.theme ? root.dataset.theme === 'dark' : matchMedia('(prefers-color-scheme: dark)').matches;
  th.addEventListener('click', e => {
    dark = !dark; paint(); say(`Theme set to ${dark ? 'dark' : 'light'}`);
    if (!e.isTrusted || pageDark() === dark) return;
    const btn = document.getElementById('theme-btn');
    if (btn) btn.click(); else { root.dataset.theme = dark ? 'dark' : 'light'; try { localStorage.setItem('dmui-theme', root.dataset.theme); } catch(err){} }
  });
  // and when the page's theme changes from anywhere else, the switch follows it
  const mo = new MutationObserver(() => { if (pageDark() !== dark){ dark = pageDark(); paint(); } });
  mo.observe(root, { attributes:true, attributeFilter:['data-theme'] }); c.offs.push(() => mo.disconnect());
  // Keyboard shortcuts, or ? anywhere in the component, opens the list of the keys the menu answers to
  const keys = on => { kf.classList.toggle('shut', !on); kf.inert = !on; };
  keys(false);
  $('.pfm-ky', r).addEventListener('click', () => { const had = pop.contains(document.activeElement); show(false); keys(true); if (had) $('.pfm-kx', r).focus({ preventScroll:true }); });
  $('.pfm-kx', r).onclick = () => { keys(false); tr.focus({ preventScroll:true }); };
  c.on(r, 'keydown', e => { if (e.key === '?' && !e.target.matches('input,textarea')){ e.preventDefault(); show(false); keys(kf.classList.contains('shut')); } });
  // signing out swaps the avatar for Sign in, which brings it back
  $('.pfm-out', r).addEventListener('click', () => { const had = pop.contains(document.activeElement); show(false); tr.hidden = true; sin.hidden = false; if (had) sin.focus({ preventScroll:true }); say(`Signed out of ${WS[ws][1]}`); });
  sin.onclick = () => { sin.hidden = true; tr.hidden = false; tr.focus({ preventScroll:true }); say('Signed in as Maya Kim'); };
  // the preview's story: open the menu, look over the workspaces, switch to Acme Labs, then open it again and flip the theme
  c.story(async s => {
    const hl = el => items().forEach(x => x.classList.toggle('hl', x === el));
    await s.beat(3); await s.tap(tr); await s.beat(2);
    hl(rows[2]); await s.point(rows[2]); await s.beat(2);
    hl(rows[1]); await s.point(rows[1]); await s.beat(2);
    await s.tap(rows[1]); s.away(); await s.beat(4);
    await s.tap(tr); await s.beat(2);
    hl(th); await s.tap(th); await s.beat(3);
    await s.tap(tr); s.away(); await s.beat(3);
  });
});
